"use client";

import React, { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { useCurrentUser } from "@/hooks/use-current-user";
import { useRouter, useSearchParams } from "next/navigation";

export default function SetupClient() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user, loading: userLoading } = useCurrentUser();
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  // maybe you passed ?plan=starter from pricing
  const planFromQuery = searchParams.get("plan");

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError("");

    if (!user) {
      setError("No user loaded yet.");
      return;
    }
    if (!user.tenantId) {
      setError("User has no tenantId. Please sign up again.");
      return;
    }

    setSaving(true);
    try {
      // update tenant with business info + plan
      await api.completeBusinessSetup(user.tenantId, {
        planId: planFromQuery ?? "starter",
        businessName: "My Business",
        businessPhone: "+1 (555) 555-5555",
      });

      router.push("/dashboard");
    } catch (err: any) {
      console.error(err);
      setError(err?.message ?? "Could not finish setup.");
      setSaving(false);
    }
  }

  if (userLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        Loading user...
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-dark-bg p-6">
      <form
        onSubmit={handleSubmit}
        className="bg-glass-bg border border-glass-border rounded-2xl p-8 w-full max-w-lg space-y-4"
      >
        <h1 className="text-2xl font-semibold">Finish your setup</h1>
        <p className="text-dark-text-secondary">
          We’ll connect your tenant and provision SMS.
        </p>

        {/* (you can add fields here) */}

        {error && <p className="text-red-400 text-sm">{error}</p>}

        <button
          type="submit"
          disabled={saving}
          className="w-full bg-brand-primary rounded-lg py-3 font-semibold"
        >
          {saving ? "Saving..." : "Continue to dashboard"}
        </button>
      </form>
    </div>
  );
}
